async function loadTopics(){const ticket=++listRequest;state.loading=true;state.error=null;renderList();try{const result=await api(`/api/topics?lang=${encodeURIComponent(dataLanguage())}${state.tag?'&tag='+encodeURIComponent(state.tag):''}`);if(ticket!==listRequest)return;state.topics=(result.topics||[]).map(topic=>({...topic,minutes:Math.max(0,(Date.now()-Date.parse(topic.updatedAt||topic.createdAt))/60000)}));state.translation=result.translation||{};}catch(error){if(ticket!==listRequest)return;state.error=error;state.topics=[];}finally{if(ticket===listRequest){state.loading=false;renderList();updateTranslation();}}}
